package online.rollnexa.config;
import lombok.RequiredArgsConstructor; import online.rollnexa.domain.*; import online.rollnexa.repository.*; import org.springframework.boot.*; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.context.annotation.*; import org.springframework.security.crypto.password.PasswordEncoder; import java.util.*;
@Configuration @Profile("dev") @RequiredArgsConstructor @ConditionalOnProperty(name="app.seed-demo-data",havingValue="true")
public class DevDataConfig {
 @Bean ApplicationRunner demo(UserRepository users,RoomRepository rooms,RoomMemberRepository members,PasswordEncoder encoder){return args->{if(users.count()>0)return;var gm=new User();gm.setUsername("NightWizard");gm.setEmail("gm@rollnexa.local");gm.setPasswordHash(encoder.encode("Rollnexa123!"));gm.setBio("GM de campañas de terror y fantasía.");users.save(gm);var p=new User();p.setUsername("PlayerOne");p.setEmail("player@rollnexa.local");p.setPasswordHash(encoder.encode("Rollnexa123!"));users.save(p);create("La Maldición de Strahd","Buscamos jugadores para comenzar una campaña oscura en Barovia.","D&D 5e","Terror,Fantasía",6,gm,rooms,members);create("One Shot: The Haunting","Misterio clásico, ideal para personas nuevas.","Call of Cthulhu","Terror,One Shot",5,gm,rooms,members);};}
 private void create(String name,String desc,String system,String tags,int cap,User gm,RoomRepository rooms,RoomMemberRepository members){var r=new Room();r.setName(name);r.setDescription(desc);r.setGameSystem(system);r.setTags(tags);r.setCampaignType(name.startsWith("One")?Room.CampaignType.ONE_SHOT:Room.CampaignType.LONG_CAMPAIGN);r.setMaxParticipants(cap);r.setJoinMode(Room.JoinMode.APPROVAL_REQUIRED);rooms.save(r);var m=new RoomMember();m.setRoom(r);m.setUser(gm);m.setRole(RoomMember.Role.GM);members.save(m);}
}
